// WASM module loader for nodebox-electron.
// Initializes eagerly on import. Call functions only after isWasmReady() returns true.

import init, {
  evaluate_library,
  get_node_templates,
  create_node,
  register_font,
  take_missing_fonts,
  export_svg,
  viewer_init,
  viewer_render,
  viewer_render_pixels,
  WasmNodeLibrary,
  // @ts-expect-error WASM module generated by wasm-pack
} from '@wasm/nodebox_electron.js';

import type { Node, NodeLibrary } from '../types/node';

export interface NodeTemplate {
  name: string;
  prototype: string;
  category: string;
  description: string;
  first_input_type: string | null;
}

let ready = false;
let readyCallbacks: (() => void)[] = [];

init().then(() => {
  ready = true;
  for (const cb of readyCallbacks) cb();
  readyCallbacks = [];
});

export function isWasmReady(): boolean {
  return ready;
}

export function onWasmReady(cb: () => void): void {
  if (ready) cb();
  else readyCallbacks.push(cb);
}

/** Add a font file to the font database of the WASM module. */
export function registerFont(data: Uint8Array): void {
  register_font(data);
}

/** Font names the last evaluations asked for that no registered font matched. */
export function takeMissingFonts(): string[] {
  return take_missing_fonts();
}

/**
 * Where the geometry of the last evaluation is drawn, in physical pixels:
 * a buffer of `width` by `height`, with the document origin at `offset`.
 */
export interface ViewerView {
  width: number;
  height: number;
  offsetX: number;
  offsetY: number;
  scale: number;
  /** Background as red, green and blue, each 0-255. */
  background: [number, number, number];
}

let viewerReady = false;

/** Create the WebGPU device and the Vello renderer for the viewer canvas. */
export async function initViewer(canvas: HTMLCanvasElement): Promise<void> {
  await viewer_init(canvas);
  viewerReady = true;
}

export function isViewerReady(): boolean {
  return viewerReady;
}

/** Draw the geometry of the last evaluation to the viewer canvas. */
export function renderViewer(view: ViewerView): void {
  if (!viewerReady) return;
  viewer_render(view.width, view.height, view.offsetX, view.offsetY, view.scale, ...view.background);
}

/** Render the geometry of the last evaluation offscreen and return its RGBA pixels. */
export function renderViewerPixels(view: ViewerView): Promise<Uint8Array> {
  return viewer_render_pixels(view.width, view.height, view.offsetX, view.offsetY, view.scale, ...view.background);
}

/** Render the geometry of the last evaluation as an SVG document. */
export function exportSvg(width: number, height: number, background: [number, number, number]): string {
  return export_svg(width, height, ...background);
}

export function evaluateLibrary(libraryJson: string, filesJson: string, frame: number): string {
  return evaluate_library(libraryJson, filesJson, frame);
}

let cachedTemplates: NodeTemplate[] | null = null;

export function getNodeTemplates(): NodeTemplate[] {
  if (cachedTemplates) return cachedTemplates;
  const json = get_node_templates();
  cachedTemplates = JSON.parse(json) as NodeTemplate[];
  return cachedTemplates;
}

export function createNodeFromTemplate(
  templateName: string,
  libraryJson: string,
  x: number,
  y: number,
): Node {
  const json = create_node(templateName, libraryJson, x, y);
  return JSON.parse(json) as Node;
}

export function parseNdbx(ndbxContent: string): NodeLibrary {
  const lib = WasmNodeLibrary.from_ndbx(ndbxContent);
  try {
    return JSON.parse(lib.to_json()) as NodeLibrary;
  } finally {
    lib.free();
  }
}

export function serializeNdbx(library: NodeLibrary): string {
  const lib = WasmNodeLibrary.from_json(JSON.stringify(library));
  try {
    return lib.to_ndbx();
  } finally {
    lib.free();
  }
}
